import {createOfflineCombat} from './offline-combat.js?v=2026.11.10-performance';
import {createMapCombat} from './combat-map.js?v=2026.11.10-performance';
import {fleetMaxHP} from './ship-rules.js?v=2026.11.10-performance';
import {combatProfile,combatEligible,reserveLoss,returnReserve,openBattle,fireCannon,finishExpired,claimBattle,fireAtPirate,defeatNPC,npcSlotChanges,PIRATE_ZONES,cargoCount,addCargo} from './combat-core.js?v=2026.11.10-performance';
import {cannonStats,currentHP} from './cannons.js?v=2026.11.10-performance';
import {usedSpace,capacity} from './engine.js?v=2026.11.10-performance';
import {mapDistance} from './world-wrap.js?v=2026.11.10-performance';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roll=()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296;
export function createCombat(api){
 const a=api.account,get=api.getState;let raids=null,selectedNPC=null,npcMessage='',slot=null,room=null,roomId=null,invites={},stops=[],positionStop=null,roomStop=null,positions={},sending=false,preparing=null,busy=false,lastProfile='',lastPos='',lastPosAt=0,lastProfileAt=0;
 const mapUI=createMapCombat({now,screenPoint:api.screenPoint,fire:id=>safe(()=>raids?.hasRoom()?raids.fire(id):selectedNPC?shootNPC(id):shoot(id))(),retreat:()=>safe(async()=>{if(raids?.hasRoom())return raids.retreat();if(selectedNPC){await commit('personal',a.uid,(game,_c,time)=>({...defeatNPC(game,time),extras:{['combatSlots/'+a.uid]:null,['combatVaults/'+a.uid]:null}}));selectedNPC=null;renderMap();}else{await end(true);paintBattle();}})(),dismiss:()=>{selectedNPC=null;mapUI.render(null);notice();}});
 raids=createOfflineCombat({...api,prepare,commit,effects:mapUI,render:renderMap});
 const cue=document.createElement('button');cue.className='combat-alert';cue.hidden=true;cue.onclick=show;$('.chart').append(cue);
 function now(){return Date.now()+(a.serverOffset||0);}const ref=path=>a.sdk.ref(a.db,'gameV2/'+path),read=async path=>(await a.sdk.get(ref(path))).val();
 function myPosition(){return {point:[...get().position],at:now()};}
 function peer(uid){return api.visible().find(p=>p.uid===uid);}
 function profileAt(uid,p){const boat=peer(uid);if(uid===a.uid)return {...p,...myPosition()};if(!boat)throw Error('상대 선장이 내 시야 안에 없어요.');return {...p,point:[boat.lon,boat.lat],at:boat.updatedAt};}
 async function commit(kind,key,fn){if(busy)throw Error('이전 처리를 확인 중이에요.');busy=true;try{const result=await a.atomicAction(kind,key,fn);api.changed();if(result?.message)api.toast(result.message);if(result?.broken){api.pause();setTimeout(()=>api.rescue(),0);}return result;}finally{busy=false;renderMap();}}
 function notice(){cue.hidden=(!slot&&!Object.keys(invites).length)||!mapUI.deck.hidden;cue.textContent=slot?(slot.startsWith('npc:')?'⚔ 해적 전투 계속하기':room?.status==='closed'?'⚑ 전투 결과·정산 받기':'⚔ 전투 중 · 대포 열기'):'⚔ 결투 요청 '+Object.keys(invites).length+'건';}
 async function connect(){if(!a.ready)return;dispose();slot=await read('combatSlots/'+a.uid);if(slot)watchRoom(slot);const s=a.sdk;stops.push(s.onValue(ref('combatSlots/'+a.uid),snap=>{const next=snap.val();if(next!==slot){slot=next;watchRoom(next);}notice();}));stops.push(s.onValue(s.query(ref('combatInvites/'+a.uid),s.orderByChild('at'),s.startAt(now()-60000),s.limitToLast(10)),snap=>{invites=snap.val()||{};notice();}));await raids.connect();await publish(true);if(get().port&&!slot&&get().battleReserve)await releaseIfPort();stops.push(()=>clearInterval(timer));const timer=setInterval(()=>{publish();refreshTimes();},250);notice();}
 function watchRoom(id){roomStop?.();positionStop?.();roomStop=positionStop=null;room=null;roomId=id;positions={};if(id?.startsWith('raid:')){delete get().battleId;selectedNPC=null;raids.watch(id.slice(5));renderMap();notice();return;}if(!id||id.startsWith('npc:')){delete get().battleId;if(id?.startsWith('npc:'))selectedNPC=get().npcBattle?.zoneId||selectedNPC;renderMap();notice();return;}selectedNPC=null;get().battleId=id;roomStop=a.sdk.onValue(ref('shared/battles/'+id),snap=>{const previous=room;room=snap.val()?.content||null;if(room?.status==='active'&&room.mode==='duel')api.pause();if(room?.status==='closed')positionStop?.();if(room&&!previous){api.close();api.focus?.(room.players[room.a===a.uid?room.b:room.a].point);}if(room?.event?.kind==='shot'&&room.event.sequence!==previous?.event?.sequence&&now()-room.event.at<5000){const actor=room.event.actor,target=actor===room.a?room.b:room.a,from=positions[actor]?.point||room.players[actor].point,to=positions[target]?.point||room.players[target].point;if(mapDistance(get().position,to)<=180&&mapDistance(get().position,from)<=180)mapUI.shot(id+':'+room.event.sequence,from,to,room.event);}renderMap();notice();});positionStop=a.sdk.onValue(ref('combatPositions/'+id),snap=>{positions=snap.val()||{};renderMap();});}
 async function publish(force=false){if(!a.ready||!a.sdk||sending||a.lost)return;sending=true;try{const p=combatProfile(get(),a.name,now()),{point,at,...info}=p,signature=JSON.stringify(info);if(force||signature!==lastProfile||now()-lastProfileAt>=30000){if(force||signature!==lastProfile)await a.sdk.set(ref('combatProfiles/'+a.uid),{...info,at:a.sdk.serverTimestamp()});else await a.sdk.update(ref('combatProfiles/'+a.uid),{at:a.sdk.serverTimestamp()});lastProfile=signature;lastProfileAt=now();}
  if(room?.status==='active'){const pos=myPosition(),sig=JSON.stringify(pos.point.map(n=>+n.toFixed(5))),interval=room.mode==='duel'?250:2000;if((sig!==lastPos&&now()-lastPosAt>=interval)||now()-lastPosAt>=30000){await a.sdk.set(ref('combatPositions/'+roomId+'/'+a.uid),{point:pos.point,at:a.sdk.serverTimestamp()});lastPos=sig;lastPosAt=now();}}
 }catch{/* A failed profile publish protects this captain from new attacks. */}finally{sending=false;}}
 async function prepare(){if(preparing)return preparing;if(slot)throw Error('진행 중인 전투를 먼저 마치세요.');if(get().battleReserve)return true;preparing=commit('personal',a.uid,(game)=>{const reserve=reserveLoss(game,crypto.randomUUID());return {ok:true,extras:{['combatVaults/'+a.uid]:reserve}};}).then(async()=>{await publish(true);return true;}).finally(()=>preparing=null);return preparing;}
 async function releaseIfPort(){if(!get().port)return;if(slot){if(room?.status==='closed')await claim();else throw Error('전투 결과를 먼저 정산하세요.');}if(!get().battleReserve)return;await commit('personal',a.uid,game=>{if(!game.port)throw Error('입항 후 정산금을 반환하세요.');returnReserve(game);return {ok:true,extras:{['combatVaults/'+a.uid]:null}};});await publish(true);}
 async function invite(uid){if(peer(uid)?.offline)throw Error('오프라인 선장에게는 결투를 요청할 수 없어요.');if(!peer(uid))throw Error('시야 안의 선장에게 요청하세요.');await prepare();const existing=await read('combatInvites/'+uid+'/'+a.uid);if(existing&&now()-existing.at<10000)throw Error('요청 후 10초 뒤 다시 보낼 수 있어요.');await a.sdk.set(ref('combatInvites/'+uid+'/'+a.uid),{from:a.uid,name:a.name,at:a.sdk.serverTimestamp()});api.toast('결투 요청을 보냈어요. 60초 동안 수락할 수 있어요.');}
 async function begin(uid,mode){if(mode==='free'&&peer(uid)?.offline)return raids.start(uid);if(!peer(uid))throw Error('시야 안의 선장이에요. 가까운 바다에서 다시 확인하세요.');await prepare();await publish(true);const id=crypto.randomUUID(),[target,vaultA,vaultB,slotA,slotB]=await Promise.all([read('combatProfiles/'+uid),read('combatVaults/'+a.uid),read('combatVaults/'+uid),read('combatSlots/'+a.uid),read('combatSlots/'+uid)]);if(slotA||slotB)throw Error('이미 전투 중인 선장이 있어요.');const profiles={[a.uid]:combatProfile(get(),a.name,now()),[uid]:profileAt(uid,target||{})};combatEligible(profiles[a.uid],profiles[uid],now(),api.nav().clear.bind(api.nav()));await commit('battles',id,(game,c,time)=>{if(c.status)throw Error('이미 사용한 전투 번호예요.');if(game.port||game.voyage?.kind)throw Error('항구 밖 정상 항해 중에 시작하세요.');Object.assign(c,openBattle(mode,a.uid,uid,profiles,{[a.uid]:vaultA,[uid]:vaultB},time,api.nav().clear.bind(api.nav())));if(mode==='duel')c.inviteFrom=uid;game.battleId=id;return {ok:true,message:mode==='duel'?'결투를 수락했어요.':'해상 전투를 시작했어요.',extras:{['combatSlots/'+a.uid]:id,['combatSlots/'+uid]:id}};});slot=id;watchRoom(id);show();}
 async function shoot(id){await commit('battles',roomId,(_game,c,time)=>fireCannon(c,a.uid,id,time,roll(),{...positions,[a.uid]:myPosition()},api.nav().clear.bind(api.nav())));}
 async function end(surrender=false){await commit('battles',roomId,(_game,c,time)=>finishExpired(c,a.uid,time,{...positions,[a.uid]:myPosition()},surrender));}
 async function claim(){const id=roomId;const result=await commit('battles',id,(game,c,time)=>({...claimBattle(game,c,a.uid,time),extras:{['combatSlots/'+a.uid]:null,['combatVaults/'+a.uid]:null}}));slot=null;room=null;watchRoom(null);notice();await publish(true);return result;}
 function safe(fn){return async()=>{try{await fn();}catch(e){api.toast(e.message,'error');if($('#combat-message'))$('#combat-message').textContent=e.message;}};}
 function show(){if(raids.hasRoom()){api.close();return renderMap();}if(slot&&!slot.startsWith('npc:')){api.close();return paintBattle();}if(get().npcBattle)return showPirate(get().npcBattle.zoneId);const s=get(),peers=api.visible().filter(p=>p.uid!==a.uid);api.modal('선장 간 전투','대포는 항구의 대포·수리 메뉴에서 구입·장착',`<p>기본 사거리 180해리. 합의 결투는 피해 ×1.5, 명중 +10%p, 재장전 ×0.7. 항구·구조·패전 직후는 보호됩니다.</p><p>패배 시 돈 10%(최대 2,000 D), 화물 10%(최대 5상자)와 수리비를 잃고 방문한 항구로 구조돼요. 출항 전 손실 한도만 보관하며 남은 금액은 전투 뒤 또는 입항 때 반환해요.</p>${Object.entries(invites).filter(([,r])=>now()-r.at<60000).map(([uid,r])=>`<article><h3>${esc(r.name)}의 결투 요청</h3><button data-accept="${uid}">강화 결투 수락</button><button data-decline="${uid}">거절</button></article>`).join('')}<h3>시야 안 선장</h3>${peers.length?peers.map(p=>`<article><strong>${esc(p.name)}</strong><div class="dialog-actions"><button data-invite="${p.uid}">결투 요청</button><button data-free="${p.uid}">기본 대포로 공격</button></div></article>`).join(''):'<p>시야 안의 다른 배가 없어요.</p>'}<button id="combat-loot">항구에서 전리품 받기 · ${cargoCount(s.lootClaims)}/50상자</button><p id="combat-message" role="status"></p>`,'wide');document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=safe(()=>begin(b.dataset.accept,'duel')));document.querySelectorAll('[data-decline]').forEach(b=>b.onclick=safe(async()=>{await a.sdk.remove(ref('combatInvites/'+a.uid+'/'+b.dataset.decline));show();}));document.querySelectorAll('[data-invite]').forEach(b=>b.onclick=safe(()=>invite(b.dataset.invite)));document.querySelectorAll('[data-free]').forEach(b=>b.onclick=()=>confirmAttack(b.dataset.free));document.querySelectorAll('[data-pirate]').forEach(b=>b.onclick=()=>showPirate(b.dataset.pirate));document.querySelectorAll('[data-pirate-look]').forEach(b=>b.onclick=()=>api.look(PIRATE_ZONES.find(z=>z.id===b.dataset.pirateLook).point));$('#combat-loot').onclick=safe(async()=>{await releaseIfPort();await commit('personal',a.uid,game=>{if(!game.port)throw Error('항구에서 수령하세요.');if(usedSpace(game)+cargoCount(game.lootClaims)>capacity(game))throw Error('전리품을 실을 화물 공간을 비우세요.');addCargo(game.cargo,game.lootClaims);game.lootClaims={};return {ok:true,message:'전리품을 화물칸에 실었어요.'};});show();});}
 function confirmAttack(uid){api.modal('이 선장을 공격할까요?','시야 안 자유 공격',`<p>상대의 동의 없이 기본 대포 성능으로 해상 전투를 시작합니다. 상대도 반격할 수 있어요.</p><button id="free-confirm">공격 시작</button><p id="combat-message"></p>`,'small');$('#free-confirm').onclick=safe(()=>begin(uid,'free'));}
 function paintBattle(){if(!room)return api.toast('전투 정보를 불러오는 중이에요.');renderMap();}
 function refreshTimes(){renderMap();raids.tick();}
 function renderMap(){const s=get(),raidModel=raids?.model();if(raidModel){mapUI.render(raidModel);return;}if(room){const other=room.a===a.uid?room.b:room.a,me=room.players[a.uid],enemy=room.players[other],enemyPoint=positions[other]?.point||enemy.point,inRange=mapDistance(s.position,enemyPoint)<=180;mapUI.render({key:roomId,title:(room.mode==='duel'?'강화 결투 · ':'해상 포격 · ')+enemy.name,me:{...me,point:s.position},enemy:{...enemy,point:inRange?enemyPoint:null},guns:(me.guns||[]).map(g=>({...g,name:cannonStats(g,room.mode==='duel').name})),busy,inRange,closed:room.status==='closed',winner:room.winner,canRetreat:room.status==='active',message:room.status==='closed'?(room.winner===a.uid?'승리':'패배')+' · '+room.reason:(inRange?'':'표적이 시야 밖입니다. ')+(room.event?.text||'')+' · 남은 '+Math.max(0,Math.ceil((room.deadline-now())/1000))+'초',actions:room.status==='closed'?[['결과 정산·계속하기',safe(()=>claim())]]:[['시간 종료·접속 종료 판정',safe(()=>end())]]});notice();return;}if(!selectedNPC){mapUI.render(null);return;}const z=PIRATE_ZONES.find(z=>z.id===selectedNPC);if(!z){selectedNPC=null;mapUI.render(null);return;}if(now()<(s.pirateRespawns?.[z.id]||0)){selectedNPC=null;mapUI.render(null);notice();return;}const distance=mapDistance(s.position,z.point),max=[100,240,500][z.tier],respawn=Math.max(0,Math.ceil(((s.pirateRespawns?.[z.id]||0)-now())/1000)),hp=respawn?0:s.npcBattle?.zoneId===z.id?s.npcBattle.hp:max;mapUI.render({key:'npc:'+z.id,title:z.name,me:{hp:currentHP(s),maxHP:fleetMaxHP(s),point:s.position},enemy:{hp,maxHP:max,point:distance<=180?z.point:null},guns:(s.cannons||[]).filter(g=>g.shipId).map(g=>({...g,name:cannonStats(g).name})),busy,inRange:distance<=180&&!s.port&&!s.voyage?.kind,closed:!!respawn,canRetreat:!!s.npcBattle,allowClose:!s.npcBattle,message:respawn?'토벌 완료 · 재출현까지 '+Math.ceil(respawn/60)+'분':Math.round(distance)+'해리 · '+(npcMessage||'선제공격 없음 · 대포를 눌러 발사')});notice();}
 async function shootNPC(gunId){const z=PIRATE_ZONES.find(z=>z.id===selectedNPC),from=[...get().position];if(slot&&!slot.startsWith('npc:'))throw Error('선장 간 전투를 먼저 마치세요.');const result=await commit('personal',a.uid,(game,_c,time)=>{const result=fireAtPirate(game,z.id,gunId,time,[roll(),roll()],api.nav().clear.bind(api.nav()));result.extras={...npcSlotChanges(game,a.uid,slot),...(!game.battleReserve?{['combatVaults/'+a.uid]:null}:{})};return result;});npcMessage=result.message;if(result.victory)selectedNPC=null;mapUI.shot('npc:'+crypto.randomUUID(),from,z.point,result);if(result.retaliation?.fired)mapUI.shot('retaliation:'+crypto.randomUUID(),z.point,from,{hit:result.retaliation.damage>0,damage:result.retaliation.damage});renderMap();}

 function showPirate(zoneId){const z=PIRATE_ZONES.find(z=>z.id===zoneId);if(!z)return;if(now()<(get().pirateRespawns?.[z.id]||0))return api.toast('이미 토벌한 해적이에요.');if(room)return api.toast('선장 간 전투를 먼저 마치세요.');selectedNPC=zoneId;npcMessage='';api.pause();api.close();api.focus?.(z.point);renderMap();}
 function dispose(){raids?.dispose();stops.forEach(fn=>fn());stops=[];roomStop?.();positionStop?.();roomStop=positionStop=null;room=null;roomId=null;slot=null;invites={};positions={};selectedNPC=null;mapUI.render(null);notice();}
 async function onArrival(){try{if(room?.status==='active'){api.toast('항구로 이탈해 전투를 마칩니다.');await end(true);await claim();}else await releaseIfPort();}catch(e){api.toast(e.message,'error');}}
 return {connect,dispose,show,attack:uid=>confirmAttack(uid),showPirate,renderMap,prepare,releaseIfPort,publish,onArrival,active:()=>raids.active()||room?.status==='active',retreatForRescue:async()=>{if(raids.active())return raids.retreat();await end(true);await claim();},hasReserve:()=>!!get().battleReserve,blocked:()=>raids.blocked()||!!slot&&(slot.startsWith('npc:')||room?.status!=='active'||room?.mode==='duel')};
}
